Object.assign(window.CODELAB_OFFLINE_PACKS,{"topic-removealladjacentduplicatesinstringii":{"key":"topic-removealladjacentduplicatesinstringii","number":null,"title":"Remove All Adjacent Duplicates in String II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove All Adjacent Duplicates in String II.py","code":"class Solution:\n    def removeDuplicates(self, s: str, k: int) -> str:\n        l, stack, i = list(s), [], 0\n        while i < len(l):\n            if i == 0 or l[i] != l[i - 1]:\n                stack.append(1)\n            else:\n                count = stack.pop() + 1\n                if count == k:\n                    l = l[:i - k + 1] + l[i + 1:]\n                    i = i - k\n                else:\n                    stack.append(count)\n            i += 1\n        return ''.join(l)","hash":"4068f94ff1db366410b6453c949b02ff937a20b27514e2018008ba8553f86014","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-04 Leetcoding Challenge/Remove All Adjacent Duplicates in String II.py"}]},{"language":"python","name":"Remove All Adjacent Duplicates in String II.py","code":"class Solution:\n    def removeDuplicates(self, s: str, k: int) -> str:\n        stack = [['$', 0]]\n        for char in s:\n            if stack[-1][0] == char:\n                stack[-1][1] += 1\n                if stack[-1][1] == k:\n                    stack.pop()\n            else:\n                stack.append([char, 1])\n        return ''.join([entry[0] * entry[1] for entry in stack])","hash":"a81bc279acb3c1f789e8016f509dae1aeff735fc4b351a35842532bc0c3b500a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Remove All Adjacent Duplicates in String II.py"}]}],"sources":["solutions"]},"topic-removeboxes":{"key":"topic-removeboxes","number":null,"title":"Remove Boxes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Boxes.py","code":"class Solution:\n    def removeBoxes(self, boxes: List[int]) -> int:\n        @cache\n        def helper(low, high, k):\n            if low == high:\n                return 0\n            while low + 1 < high and boxes[low] == boxes[low + 1]:\n                low, k = low + 1, k + 1\n            result = (k + 1) * (k + 1) + helper(low + 1, high, 0)\n            for mid in range(low + 2, high):\n                if boxes[low] == boxes[mid]:\n                    result = max(result, helper(low + 1, mid, 0) + helper(mid, high, k + 1))\n            return result\n        return helper(0, len(boxes), 0)","hash":"18debd31235063bfab128d2474bc4aefbd9d65c12a99ffe516fcd47464bf40bb","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-08 LeetCoding Challenge/Remove Boxes.py"}]}],"sources":["solutions"]},"topic-removecomments":{"key":"topic-removecomments","number":null,"title":"Remove Comments","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Comments.py","code":"class Solution:\n    def removeComments(self, source: List[str]) -> List[str]:\n        result, inBlockComment = [], False\n        for line in source:\n            i = 0\n            if not inBlockComment:\n                newLine = []\n            while i < len(line):\n                if line[i : i + 2] == '/*' and not inBlockComment:\n                    inBlockComment = True\n                    i += 1\n                elif line[i : i + 2] == '*/' and inBlockComment:\n                    inBlockComment = False\n                    i += 1\n                elif not inBlockComment and line[i : i + 2] == '//':\n                    break\n                elif not inBlockComment:\n                    newLine.append(line[i])\n                i += 1\n            if newLine and not inBlockComment:\n                result.append(''.join(newLine))\n        return result","hash":"8609b7db07ebf585a6d0620b9b958012530e46f7cb646a8c7015ef6185f0b529","origins":[{"source":"solutions","path":"Remove Comments.py"}]}],"sources":["solutions"]},"topic-removecoveredintervals":{"key":"topic-removecoveredintervals","number":null,"title":"Remove Covered Intervals","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Covered Intervals.py","code":"class Solution:\n    def removeCoveredIntervals(self, intervals: List[List[int]]) -> int:\n        intervals.sort(key = lambda x : (x[0], -x[1]))\n        count, prevEnd = 0, 0\n        for _, end in intervals:\n            if end > prevEnd:\n                count += 1\n                prevEnd = end\n        return count","hash":"4ae55ba228d2bd7bead56888e69e89db46f5f474095a0b8791c720469d6d9a6e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Remove Covered Intervals.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/Remove Covered Intervals.py"}]}],"sources":["solutions"]},"topic-removedigitfromnumbertomaximizeresult":{"key":"topic-removedigitfromnumbertomaximizeresult","number":null,"title":"Remove Digit From Number to Maximize Result","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Digit From Number to Maximize Result.py","code":"class Solution:\n    def removeDigit(self, number: str, digit: str) -> str:\n        result = 0\n        for i in range(len(number)):\n            if number[i] == digit:\n                result = max(result, int(number[0:i] + number[i+1:]))\n        return str(result)","hash":"b93d9583dac41abaa37c4a5a5be4b033bd055d2907b728962a139031bf350d7c","origins":[{"source":"solutions","path":"Remove Digit From Number to Maximize Result.py"}]}],"sources":["solutions"]},"topic-removeduplicateletters":{"key":"topic-removeduplicateletters","number":null,"title":"Remove Duplicate Letters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Duplicate Letters.py","code":"class Solution:\n    def removeDuplicateLetters(self, s: str) -> str:\n        stack, seen, lastOccurence = deque([]), set(), {char: index for index, char in enumerate(s)}\n        for index, char in enumerate(s):\n            if char not in seen:\n                while stack and char < stack[-1] and index < lastOccurence[stack[-1]]:\n                    seen.discard(stack.pop())\n                seen.add(char)\n                stack.append(char)\n        return ''.join(stack)","hash":"daf2e13e228f1d3fce6fedc1c78f28f888ae05b3ac0a45e6a2dda119cac4dbe4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Remove Duplicate Letters.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Remove Duplicate Letters.py"}]}],"sources":["solutions"]},"topic-removeinterval":{"key":"topic-removeinterval","number":null,"title":"Remove Interval","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Interval.py","code":"class Solution:\n    def removeInterval(self, intervals: List[List[int]], toBeRemoved: List[int]) -> List[List[int]]:\n        result = []\n        for start, end in intervals:\n            if start < toBeRemoved[0]:\n                result.append([start, min(end, toBeRemoved[0])])\n            if toBeRemoved[1] < end:\n                result.append([max(start, toBeRemoved[1]), end])\n        return result","hash":"d0f1df72ca62d6a2dc535176c868297876fdf20e3756891f25978102a17c85ea","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Remove Interval.py"}]}],"sources":["solutions"]},"topic-removekdigits":{"key":"topic-removekdigits","number":null,"title":"Remove K Digits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove K Digits.py","code":"class Solution:\n    def removeKdigits(self, num: str, k: int) -> str:\n        stack = []\n        for char in num:\n            while stack and k and stack[-1] > char:\n                stack.pop()\n                k -= 1\n            if stack or char is not \"0\":\n                stack.append(char)\n        if k:\n            stack = stack[0: -k]\n        return \"\".join(stack) or \"0\"","hash":"f18ba08537a0c9738d751b2db994e4110d4ff52128eecc70b30a85bab973a1c9","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/Remove K Digits.py"}]}],"sources":["solutions"]},"topic-removelettertoequalizefrequency":{"key":"topic-removelettertoequalizefrequency","number":null,"title":"Remove Letter To Equalize Frequency","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Letter To Equalize Frequency.py","code":"class Solution:\n    def equalFrequency(self, word: str) -> bool:\n        freqMap = Counter(word)\n        for char in word:\n            freqMap[char] -= 1\n            if freqMap[char] == 0:\n                freqMap.pop(char)\n            if len(set(freqMap.values())) == 1:\n                return True\n            freqMap[char] += 1\n        return False","hash":"c1dd5d34571205ff49034dac3a9477e47251bf87346b2591c7afef1cb6027341","origins":[{"source":"solutions","path":"Remove Letter To Equalize Frequency.py"}]}],"sources":["solutions"]},"topic-removelinkedlistelements":{"key":"topic-removelinkedlistelements","number":null,"title":"Remove Linked List Elements","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Linked List Elements.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def removeElements(self, head: ListNode, val: int) -> ListNode:\n        dummyNode = ListNode(-1)\n        dummyNode.next = head\n        currentNode = dummyNode\n        while currentNode is not None and currentNode.next is not None:\n            if currentNode.next.val == val:\n                currentNode.next = currentNode.next.next\n            else:\n                currentNode = currentNode.next\n        return dummyNode.next","hash":"4cc43dd6c18ca918215cb1ef65ef2714827e160007d089163efdcd649014be5d","origins":[{"source":"solutions","path":"Linked List/Remove Linked List Elements.py"}]}],"sources":["solutions"]},"topic-removemaxnumberofedgestokeepgraphfullytraversable":{"key":"topic-removemaxnumberofedgestokeepgraphfullytraversable","number":null,"title":"Remove Max Number of Edges to Keep Graph Fully Traversable","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Max Number of Edges to Keep Graph Fully Traversable.py","code":"class Solution:\n    def maxNumEdgesToRemove(self, n: int, edges: List[List[int]]) -> int:\n        parent = [i for i in range(n + 1)]\n        \n        def findParent(x):\n            if parent[x] != x:\n                parent[x] = findParent(parent[x])\n            return parent[x]\n        \n        def unionPossible(x, y):\n            px, py = findParent(x), findParent(y)\n            if px == py:\n                return False\n            else:\n                parent[px] = py\n                return True\n        \n        result = edgesForAlice = edgesForBob = 0\n        for Type, From, To in edges:\n            if Type == 3:\n                if unionPossible(From, To):\n                    edgesForAlice += 1\n                    edgesForBob += 1\n                else:\n                    result += 1\n        parentCopy = copy.copy(parent)\n        for Type, From, To in edges:\n            if Type == 1:\n                if unionPossible(From, To):\n                    edgesForAlice += 1\n                else:\n                    result += 1\n        parent = copy.copy(parentCopy)\n        for Type, From, To in edges:\n            if Type == 2:\n                if unionPossible(From, To):\n                    edgesForBob += 1\n                else:\n                    result += 1\n        return result if edgesForAlice == edgesForBob == n - 1 else -1","hash":"2cbab3455e0b7904c5761b7c88c97b68bd534782e7bae62a8b030ed0a35bf171","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Remove Max Number of Edges to Keep Graph Fully Traversable.py"},{"source":"solutions","path":"Weekly Contests/Weekly Contest 205/Remove Max Number of Edges to Keep Graph Fully Traversable.py"}]}],"sources":["solutions"]},"topic-removeoutermostparentheses":{"key":"topic-removeoutermostparentheses","number":null,"title":"Remove Outermost Parentheses","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Outermost Parentheses.py","code":"class Solution:\n    def removeOuterParentheses(self, S: str) -> str:\n        primitiveEndIndices = set([0])\n        count = 0\n        for i, char in enumerate(S):\n            if char == '(':\n                count += 1\n            elif char == ')':\n                count -= 1\n            if count == 0:\n                primitiveEndIndices.add(i)\n                primitiveEndIndices.add(i + 1)\n        result = []\n        for i in range(len(S)):\n            if i not in primitiveEndIndices:\n                result.append(S[i])\n        return ''.join(result)","hash":"f3b8318fe6a4efad7b63a9603992d892acf871e8026f00bd76e30cf0428b48c5","origins":[{"source":"solutions","path":"Mock Interviews/Google/Online Assessment 04/Remove Outermost Parentheses.py"}]}],"sources":["solutions"]},"topic-removepalindromicsubsequences":{"key":"topic-removepalindromicsubsequences","number":null,"title":"Remove Palindromic Subsequences","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Palindromic Subsequences.py","code":"class Solution:\n    def removePalindromeSub(self, s: str) -> int:\n        def isPalindrome(s):\n            low, high = 0, len(s) - 1\n            while low < high:\n                if s[low] != s[high]:\n                    return False\n                low, high = low + 1, high - 1\n            return True\n        if not s:\n            return 0\n        if isPalindrome(s):\n            return 1\n        return 2","hash":"5c79c6dd2489c4cb7a0ed0f12dcca8dfb3fa4e3ac6e301b220a0c4efab46af04","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-03 Leetcoding Challenge/Remove Palindromic Subsequences.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-06 Leetcoding Challenge/Remove Palindromic Subsequences.py"}]}],"sources":["solutions"]},"topic-removestonestominimizethetotal":{"key":"topic-removestonestominimizethetotal","number":null,"title":"Remove Stones to Minimize the Total","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Stones to Minimize the Total.py","code":"class Solution:\n    def minStoneSum(self, piles: List[int], k: int) -> int:\n        heap = [-1 * pile for pile in piles]\n        heapq.heapify(heap)\n        for i in range(k):\n            maxPile = -1 * heapq.heappop(heap)\n            newPile = maxPile - math.floor(maxPile / 2)\n            heapq.heappush(heap, -1 * newPile)\n        return -1 * sum(heap)","hash":"8d730f4e379c7077bce45fc85f544351af7ca2d5b1a32dedc601076abaabf899","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Remove Stones to Minimize the Total.py"}]}],"sources":["solutions"]},"topic-removesubfoldersfromthefilesystem":{"key":"topic-removesubfoldersfromthefilesystem","number":null,"title":"Remove Sub Folders from the Filesystem","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Sub-Folders from the Filesystem.py","code":"class Solution:\n    def removeSubfolders(self, folder: List[str]) -> List[str]:\n        folder.sort()\n        result = [folder[0],]\n        prev, prevLen = folder[0] + '/', len(folder[0]) + 1\n        for f in folder[1:]:\n            if f[:prevLen] != prev:\n                result.append(f)\n                prev, prevLen = f + '/', len(f) + 1\n        return result","hash":"99cc2c72602ad8d37bf8ee6bb2d03135e3e1ce3acde28eabc24cfbe7530e4421","origins":[{"source":"solutions","path":"Remove Sub-Folders from the Filesystem.py"}]}],"sources":["solutions"]},"topic-removevowelsfromastring":{"key":"topic-removevowelsfromastring","number":null,"title":"Remove Vowels from a String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Remove Vowels from a String.py","code":"class Solution:\n    def removeVowels(self, S: str) -> str:\n        S, result, VOWELS = list(S), [], set(['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U']) \n        for char in S:\n            if char not in VOWELS:\n                result.append(char)\n        return ''.join(result)","hash":"691310d81705581d195f0b5540fee7268b23be53b4ff5ac4c5f7e84787262e38","origins":[{"source":"solutions","path":"Remove Vowels from a String.py"}]}],"sources":["solutions"]},"topic-removingstarsfromastring":{"key":"topic-removingstarsfromastring","number":null,"title":"Removing Stars From a String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Removing Stars From a String.py","code":"class Solution:\n    def removeStars(self, s: str) -> str:\n        stack = deque([])\n        for char in s:\n            if char != '*':\n                stack.append(char)\n            elif len(stack) > 0:\n                stack.pop()\n        return ''.join(stack)","hash":"c85b0552b697710852d8a96081f0fe00e42342ae848db0293a26b76a114f9191","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Removing Stars From a String.py"}]}],"sources":["solutions"]},"topic-reorderdatainlogfiles":{"key":"topic-reorderdatainlogfiles","number":null,"title":"Reorder Data in Log Files","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reorder Data in Log Files.py","code":"class Solution:\n    def reorderLogFiles(self, logs: List[str]) -> List[str]:\n        logsMap = defaultdict(list)\n        for log in logs:\n            if log.split()[1].isdigit():\n                logsMap['digit'].append(log)\n            else:\n                logsMap['letter'].append((' '.join(log.split()[1:]) + ' ' + log.split()[0], log))\n        logsMap['letter'].sort()\n        result = list(x[1] for x in logsMap['letter'])\n        result.extend(logsMap['digit'])\n        return result","hash":"3390390454a328d908e3f9cd8ccfed775519967f32b0a3b3de79a96a256e815f","origins":[{"source":"solutions","path":"Amazon Interview Questions/Reorder Data in Log Files.py"}]}],"sources":["solutions"]},"topic-reorderlist":{"key":"topic-reorderlist","number":null,"title":"Reorder List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reorder List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def reorderList(self, head: ListNode) -> None:\n        \"\"\"\n        Do not return anything, modify head in-place instead.\n        \"\"\"\n        if not head:\n            return None\n        fast = slow = head\n        while fast and fast.next:\n            fast, slow = fast.next.next, slow.next\n        prev, curr = None, slow\n        while curr:\n            curr.next, prev, curr = prev, curr, curr.next\n        first, second = head, prev\n        while second.next:\n            first.next, first = second, first.next\n            second.next, second = first, second.next","hash":"257ef2d43364012f2fe53c923bccddd6eaa91ebc64ececb0b78dcfd13e68d352","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Reorder List.py"}]}],"sources":["solutions"]},"topic-reorderroutestomakeallpathsleadtothecityzero":{"key":"topic-reorderroutestomakeallpathsleadtothecityzero","number":null,"title":"Reorder Routes to Make All Paths Lead to the City Zero","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reorder Routes to Make All Paths Lead to the City Zero.py","code":"class Solution:\n    def minReorder(self, n: int, connections: List[List[int]]) -> int:\n        result = 0\n        neighbours = defaultdict(set)\n        directedEdge = defaultdict(set)\n        for From, To in connections:\n            directedEdge[From].add(To)\n            neighbours[From].add(To)\n            neighbours[To].add(From)\n        seen = set()\n        \n        def dfs(city):\n            nonlocal result\n            for neighbour in neighbours[city]:\n                if neighbour not in seen:\n                    seen.add(city)\n                    if city not in directedEdge[neighbour]:\n                        result += 1\n                    dfs(neighbour)\n                    \n        dfs(0)\n        return result","hash":"d333cdd9fde57ae4571463b91dc4192ba66f6b80820ab90835647bd31b909836","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-03 Leetcoding Challenge/Reorder Routes to Make All Paths Lead to the City Zero.py"},{"source":"solutions","path":"Mock Interviews/Google/Online Assessment 01/Reorder Routes to Make All Paths Lead to the City Zero.py"}]}],"sources":["solutions"]},"topic-repeateddnasequences":{"key":"topic-repeateddnasequences","number":null,"title":"Repeated DNA Sequences","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Repeated DNA Sequences.py","code":"class Solution:\n    def findRepeatedDnaSequences(self, s: str) -> List[str]:\n        L, n = 10, len(s)\n        if n <= L:\n            return []\n        base = 4\n        baseL = pow(base, L)\n        charMap = {'A': 0, 'C': 1, 'G': 2, 'T': 3}\n        nums = [charMap[char] for char in s]\n        currentHash = 0\n        for num in nums[:L]:\n            currentHash = (currentHash * base) + num\n        seen, result = set([currentHash,]), set()\n        for i in range(1, n - L + 1):\n            currentHash = ((currentHash * base) - (nums[i - 1] * baseL)) + nums[i + L - 1]\n            if currentHash in seen:\n                result.add(s[i : i + L])\n            seen.add(currentHash)\n        return result","hash":"2399e36456134bad095c6394758d9f1ccab0d40c8fc118fa1e1e0f6db619a9f2","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Repeated DNA Sequences.py"},{"source":"solutions","path":"Repeated DNA Sequences.py"}]}],"sources":["solutions"]},"topic-repeatedsubstringpattern":{"key":"topic-repeatedsubstringpattern","number":null,"title":"Repeated Substring Pattern","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Repeated Substring Pattern.py","code":"class Solution:\n    def repeatedSubstringPattern(self, s: str) -> bool:\n        return s in (s + s)[1:-1]","hash":"c77ad16cb7397f22998c79c59588491b9745e1bc5ce2a3b5c0af46c8e03015e7","origins":[{"source":"solutions","path":"Mock Interviews/Google/Online Assessment 02/Repeated Substring Pattern.py"}]}],"sources":["solutions"]},"topic-repeatedsubstringpatternconcatenation":{"key":"topic-repeatedsubstringpatternconcatenation","number":null,"title":"Repeated Substring Pattern Concatenation","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Repeated Substring Pattern - Concatenation.py","code":"class Solution:\n    def repeatedSubstringPattern(self, s: str) -> bool:\n        return s in (s + s)[1:-1]","hash":"c77ad16cb7397f22998c79c59588491b9745e1bc5ce2a3b5c0af46c8e03015e7","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Repeated Substring Pattern - Concatenation.py"}]}],"sources":["solutions"]},"topic-repeatedsubstringpatternkmp":{"key":"topic-repeatedsubstringpatternkmp","number":null,"title":"Repeated Substring Pattern KMP","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Repeated Substring Pattern - KMP.py","code":"class Solution:\n    def repeatedSubstringPattern(self, s: str) -> bool:\n        n = len(s)\n        dp = [0] * n\n        for i in range(1, n):\n            j = dp[i - 1]\n            while j > 0 and s[i] != s[j]:\n                j = dp[j - 1]\n            if s[i] == s[j]:\n                j += 1\n            dp[i] = j\n        l = dp[n - 1]\n        return l != 0 and n % (n - l) == 0","hash":"143420311b79dc237dbe949ea58fd82f0c13df0a614dc6bf0e3343ce922d747f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Repeated Substring Pattern - KMP.py"}]}],"sources":["solutions"]},"topic-replacealldigitswithcharacters":{"key":"topic-replacealldigitswithcharacters","number":null,"title":"Replace All Digits with Characters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Replace All Digits with Characters.py","code":"class Solution:\n    def replaceDigits(self, s: str) -> str:\n        l, N = list(s), len(s)\n        for i in range(1, N, 2):\n            l[i] = chr(ord(l[i - 1]) + int(l[i]))\n        return ''.join(l)","hash":"565235a6e8f0718ba2df3702d9b5a2085b2b58fd6227f579f472242113e6a6f8","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 51/Replace All Digits with Characters.py"}]}],"sources":["solutions"]},"topic-replaceallquestionmarkstoavoidconsecutiverepeatingcharacters":{"key":"topic-replaceallquestionmarkstoavoidconsecutiverepeatingcharacters","number":null,"title":"Replace All question marks to Avoid Consecutive Repeating Characters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Replace All question marks to Avoid Consecutive Repeating Characters.py","code":"class Solution:\n    def modifyString(self, s: str) -> str:\n        sLen, sList = len(s), list(s)\n        CHARACTERS = [chr(ord('a') + i) for i in range(26)]\n        for i, c in enumerate(sList):\n            if c == '?':\n                charIndex = 0\n                while (i > 0 and sList[i - 1] != '?' and sList[i - 1] == CHARACTERS[charIndex]) or (i < sLen - 1 and sList[i + 1] != '?' and sList[i + 1] == CHARACTERS[charIndex]):\n                    charIndex += 1\n                sList[i] = CHARACTERS[charIndex]\n        return ''.join(sList)","hash":"63af714973ce086e60386b71979709987d4cfb66d981ef6a3484a44ae2c1e8c3","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 205/Replace All question marks to Avoid Consecutive Repeating Characters.py"}]}],"sources":["solutions"]},"topic-replaceelementswithgreatestelementonrightside":{"key":"topic-replaceelementswithgreatestelementonrightside","number":null,"title":"Replace Elements with Greatest Element on Right Side","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Replace Elements with Greatest Element on Right Side.py","code":"class Solution:\n    def replaceElements(self, arr: List[int]) -> List[int]:\n        maxTillNow = -1\n        for i in range(len(arr) - 1, -1, -1):\n            arr[i], maxTillNow = maxTillNow, max(arr[i], maxTillNow)\n        return arr","hash":"f909429fb8015f939941cd717bab2bba70f15d351660b1529ba43e5feca66437","origins":[{"source":"solutions","path":"Arrays/Replace Elements with Greatest Element on Right Side.py"}]}],"sources":["solutions"]},"topic-replacewords":{"key":"topic-replacewords","number":null,"title":"Replace Words","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Replace Words.py","code":"class Solution:\n    def replaceWords(self, dictionary: List[str], sentence: str) -> str:\n        Trie = lambda : defaultdict(Trie)\n        trie = Trie()\n        END = True\n        for word in dictionary:\n            current = trie\n            for char in word:\n                current = current.setdefault(char, Trie())\n            current[END] = word\n        \n        def replace(word):\n            current = trie\n            for char in word:\n                if char not in current or END in current:\n                    break\n                current = current[char]\n            return current.get(END, word)\n        \n        return ' '.join(map(replace, sentence.split(' ')))","hash":"9d3735b35136b917d7da042882c7090a4d68d2edd1fed2e38c94a4b737faa579","origins":[{"source":"solutions","path":"Trie/Replace Words.py"}]}],"sources":["solutions"]},"topic-reshapethematrix":{"key":"topic-reshapethematrix","number":null,"title":"Reshape the Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reshape the Matrix.py","code":"class Solution:\n    def matrixReshape(self, mat: List[List[int]], r: int, c: int) -> List[List[int]]:\n        if len(mat) == 0 or (r * c != len(mat) * len(mat[0])):\n            return mat\n        result, count = [[0] * c for _ in range(r)], 0\n        for i in range(len(mat)):\n            for j in range(len(mat[0])):\n                result[count // c][count % c], count = mat[i][j], count + 1\n        return result","hash":"e219572ff034e99bb168c341e255ec2b956c224c7630915cc0c49107958ba85a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-07 Leetcoding Challenge/Reshape the Matrix.py"}]}],"sources":["solutions"]},"topic-reversebits":{"key":"topic-reversebits","number":null,"title":"Reverse Bits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reverse Bits.py","code":"class Solution:\n    def reverseBits(self, n: int) -> int:\n        result = 0\n        for _ in range(32):\n            result = (result << 1) + (n & 1)\n            n >>= 1\n        return result","hash":"c03e40d99a5a4b9553c847950fe87dc084e013e8e974f8b5d4a012790114c5fe","origins":[{"source":"solutions","path":"Reverse Bits.py"}]}],"sources":["solutions"]},"topic-reverselinkedlist":{"key":"topic-reverselinkedlist","number":null,"title":"Reverse Linked List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reverse Linked List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def reverseList(self, head: ListNode) -> ListNode:\n        if head is None or head.next is None:\n            return head\n        tempNode = self.reverseList(head.next)\n        head.next.next = head\n        head.next = None\n        return tempNode","hash":"0095d0979bfbd2373ed4c35838559af4ead690d07d05f80f2aafa3c3ec49412a","origins":[{"source":"solutions","path":"Linked List/Reverse Linked List.py"},{"source":"solutions","path":"Microsoft Interview Questions/Reverse Linked List.py"}]}],"sources":["solutions"]},"topic-reverselinkedlistiterative":{"key":"topic-reverselinkedlistiterative","number":null,"title":"Reverse Linked List Iterative","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reverse Linked List - Iterative.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def reverseList(self, head: ListNode) -> ListNode:\n        prevNode = None\n        currentNode = head\n        while currentNode:\n            tempNode = currentNode.next\n            currentNode.next = prevNode\n            prevNode = currentNode\n            currentNode = tempNode\n        return prevNode","hash":"3de7bb32b3fa15ecad5c9d7ae07e53ba7dbfe3f35b15089e56c21ce81668c97e","origins":[{"source":"solutions","path":"Recursion I/Reverse Linked List - Iterative.py"}]}],"sources":["solutions"]},"topic-reverselinkedlistrecursive":{"key":"topic-reverselinkedlistrecursive","number":null,"title":"Reverse Linked List Recursive","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reverse Linked List - Recursive.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def reverseList(self, head: ListNode) -> ListNode:\n        if head is None or head.next is None:\n            return head\n        tempNode = self.reverseList(head.next)\n        head.next.next = head\n        head.next = None\n        return tempNode","hash":"0095d0979bfbd2373ed4c35838559af4ead690d07d05f80f2aafa3c3ec49412a","origins":[{"source":"solutions","path":"Recursion I/Reverse Linked List - Recursive.py"}]}],"sources":["solutions"]},"topic-reverseprefixofword":{"key":"topic-reverseprefixofword","number":null,"title":"Reverse Prefix of Word","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reverse Prefix of Word.py","code":"class Solution:\n    def reversePrefix(self, word: str, ch: str) -> str:\n        if ch not in word:\n            return word\n        reqIndex = word.index(ch)\n        return word[:reqIndex + 1][::-1] + word[reqIndex + 1:]","hash":"4db9477bfabfa99f2d3fa041728ee6ea21b8a01910a38b200be905d73d5e3c8d","origins":[{"source":"solutions","path":"Reverse Prefix of Word.py"}]}],"sources":["solutions"]},"topic-reversestring":{"key":"topic-reversestring","number":null,"title":"Reverse String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reverse String.py","code":"class Solution:\n    def reverseString(self, s: List[str]) -> None:\n        \"\"\"\n        Do not return anything, modify s in-place instead.\n        \"\"\"\n        def helper(left, right):\n            if left < right:\n                s[left], s[right] = s[right], s[left]\n                helper(left + 1, right - 1)\n        helper(0, len(s) - 1)","hash":"3da9a1b2152e93080acfa818070e4620bfb726c2b5c9a656e577e71c57567713","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-04 Leetcoding Challenge/Reverse String.py"},{"source":"solutions","path":"Microsoft Interview Questions/Reverse String.py"},{"source":"solutions","path":"Recursion I/Reverse String.py"}]}],"sources":["solutions"]},"topic-reversestringii":{"key":"topic-reversestringii","number":null,"title":"Reverse String II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reverse String II.py","code":"class Solution:\n    def reverseStr(self, s: str, k: int) -> str:\n        a = list(s)\n        for i in range(0, len(a), 2*k):\n            a[i:i+k] = reversed(a[i:i+k])\n        return ''.join(a)","hash":"f2288755903af4d805f5e347a01039253a8530c31969fd432caded269f907ebf","origins":[{"source":"solutions","path":"Reverse String II.py"}]}],"sources":["solutions"]},"topic-reversewordsinastringii01":{"key":"topic-reversewordsinastringii01","number":null,"title":"Reverse Words in a String II 01","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reverse Words in a String II - 01.py","code":"class Solution:\n    def reverseWords(self, s: List[str]) -> None:\n        \"\"\"\n        Do not return anything, modify s in-place instead.\n        \"\"\"\n        def helper(left, right):\n            if left < right:\n                s[left], s[right] = s[right], s[left]\n                helper(left + 1, right - 1)\n        helper(0, len(s) - 1)\n        start = 0\n        for end, char in enumerate(s):\n            if char == ' ':\n                helper(start, end - 1)\n                start = end + 1\n            if end == len(s) - 1:\n                helper(start, end)","hash":"98526ee9d881facda994ccef000a053b06ede9030187020c33152e631e022d8d","origins":[{"source":"solutions","path":"Microsoft Interview Questions/Reverse Words in a String II - 01.py"}]}],"sources":["solutions"]},"topic-reversewordsinastringii02":{"key":"topic-reversewordsinastringii02","number":null,"title":"Reverse Words in a String II 02","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Reverse Words in a String II - 02.py","code":"class Solution:\n    def reverseWords(self, s: List[str]) -> None:\n        \"\"\"\n        Do not return anything, modify s in-place instead.\n        \"\"\"\n        s[:] = list(' '.join(''.join(s).split()[::-1]))","hash":"657539709da06f1822dc66889450a4ccdb3011a9c3914c7997f859189b35526e","origins":[{"source":"solutions","path":"Microsoft Interview Questions/Reverse Words in a String II - 02.py"}]}],"sources":["solutions"]},"topic-richestcustomerwealth":{"key":"topic-richestcustomerwealth","number":null,"title":"Richest Customer Wealth","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Richest Customer Wealth.py","code":"class Solution:\n    def maximumWealth(self, accounts: List[List[int]]) -> int:\n        return max(sum(person) for person in accounts)","hash":"79a27c9333a9c8bbf94d1931425fcac2ca01d764d7a75d2d200c255aee3d2720","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/Richest Customer Wealth.py"}]}],"sources":["solutions"]},"topic-ringsandrods":{"key":"topic-ringsandrods","number":null,"title":"Rings and Rods","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Rings and Rods.py","code":"class Solution(object):\n    def countPoints(self, rings):\n        \"\"\"\n        :type rings: str\n        :rtype: int\n        \"\"\"\n        hashMap = [[False, False, False] for _ in range(10)]\n        charMap = {'R': 0, 'G': 1, 'B': 2}\n        for i in range(0, len(rings), 2):\n            hashMap[int(rings[i + 1])][charMap[rings[i]]] = True\n        count = 0\n        for m in hashMap:\n            if m[0] == m[1] == m[2] == True:\n                count += 1\n        return count","hash":"25e0b8068ac454dba750184c3fe5a55a17d936034565e455a96e40384a43c7a7","origins":[{"source":"solutions","path":"Rings and Rods.py"}]}],"sources":["solutions"]},"topic-risingtemperature":{"key":"topic-risingtemperature","number":null,"title":"Rising Temperature","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"sql","name":"Rising Temperature.sql","code":"SELECT w1.id AS 'Id' FROM weather w1 JOIN weather w2 ON DATEDIFF(w1.recordDate, w2.recordDate) = 1 AND w1.Temperature > w2.Temperature;","hash":"cabd99ea8850ee6e2bda94eceae8ccd2a397933f4c563e8cbe65d78e80d91473","origins":[{"source":"solutions","path":"Rising Temperature.sql"}]}],"sources":["solutions"]},"topic-robotboundedincircle":{"key":"topic-robotboundedincircle","number":null,"title":"Robot Bounded In Circle","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Robot Bounded In Circle.py","code":"class Solution:\n    def isRobotBounded(self, instructions: str) -> bool:\n        DIRECTIONS = [(1, 0), (0, 1), (-1, 0), (0, -1)]\n        x = y = direction = 0\n        for i in instructions:\n            if i == 'R':\n                direction = (direction + 1) % 4\n            elif i == 'L':\n                direction = (direction + 3) % 4\n            else:\n                x += DIRECTIONS[direction][0]\n                y += DIRECTIONS[direction][1]\n        return (x == 0 and y == 0) or direction != 0","hash":"31d97cd4422dd1685bf99161bd6646a2edf51cf5980cb5ae0f2724226d860644","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Robot Bounded In Circle.py"}]},{"language":"python","name":"Robot Bounded In Circle.py","code":"class Solution(object):\n    def isRobotBounded(self, instructions):\n        \"\"\"\n        :type instructions: str\n        :rtype: bool\n        \"\"\"\n        DIR = [(1, 0), (0, 1), (-1, 0), (0, -1)]\n        x = y = dir = 0\n        for char in instructions:\n            if char == 'L':\n                dir = (dir + 1) % 4\n            elif char == 'R':\n                dir = (dir - 1) % 4\n            else:\n                x, y = x + DIR[dir][0], y + DIR[dir][1]\n        return x == 0 and y == 0 or dir > 0\n# Robot will move in circle if the end direction is not North or it is at origin","hash":"92245fe593e2718e55e35b4bafa3edb5f177192b2da2bfcdd1817cf95c9cdcd0","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/Robot Bounded In Circle.py"}]}],"sources":["solutions"]},"topic-robotreturntoorigin":{"key":"topic-robotreturntoorigin","number":null,"title":"Robot Return to Origin","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Robot Return to Origin.py","code":"class Solution:\n    def judgeCircle(self, moves: str) -> bool:\n        frequency = Counter(moves)\n        return frequency.get('U', 0) == frequency.get('D', 0) and frequency.get('L', 0) == frequency.get('R', 0)","hash":"067e7bbc22454d9235420f784d230d26438681d9ad3b3f0f706b097738dab802","origins":[{"source":"solutions","path":"Robot Return to Origin.py"}]}],"sources":["solutions"]},"topic-rootequalssumofchildren":{"key":"topic-rootequalssumofchildren","number":null,"title":"Root Equals Sum of Children","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Root Equals Sum of Children.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def checkTree(self, root: Optional[TreeNode]) -> bool:\n        return root.left.val + root.right.val == root.val","hash":"314a4bc7028a4779aec02c64dbe7a2e0f30deb4bfa600a78520d82330c4aaa29","origins":[{"source":"solutions","path":"Root Equals Sum of Children.py"}]}],"sources":["solutions"]},"topic-rotatearray":{"key":"topic-rotatearray","number":null,"title":"Rotate Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Rotate Array.py","code":"class Solution:\n    def rotate(self, nums: List[int], k: int) -> None:\n        \"\"\"\n        Do not return anything, modify nums in-place instead.\n        \"\"\"\n        def reverse(start, end):\n            while start < end:\n                nums[start], nums[end] = nums[end], nums[start]\n                start, end = start + 1, end - 1\n        \n        n = len(nums)\n        k %= n\n        reverse(0, n - 1)\n        reverse(0, k - 1)\n        reverse(k, n - 1)","hash":"59395716e309a9e20fb09766f768cc6f9d51beb82dcf28476e18a7cfa8ffb288","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Rotate Array.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/Rotate Array.py"}]}],"sources":["solutions"]},"topic-rotateddigits":{"key":"topic-rotateddigits","number":null,"title":"Rotated Digits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Rotated Digits.py","code":"class Solution:\n    def rotatedDigits(self, N: int) -> int:\n        A = list(map(int, str(N)))\n        memo = {}\n        def dp(i, equalityFlag, involutionFlag):\n            if i == len(A):\n                return +(involutionFlag)\n            if (i, equalityFlag, involutionFlag) not in memo:\n                result = 0\n                for d in range(A[i] + 1 if equalityFlag else 10):\n                    if d in {3, 4, 7}:\n                        continue\n                    result += dp(i + 1, equalityFlag and d == A[i], involutionFlag or d in {2, 5, 6, 9})\n                memo[(i, equalityFlag, involutionFlag)] = result\n            return memo[(i, equalityFlag, involutionFlag)]\n        return dp(0, True, False)","hash":"eaa283210d39bf3806a8572926f4adefe6ca8aa9df65eff094f8d9cfb3f8ad1c","origins":[{"source":"solutions","path":"Mock Interviews/Google/Online Assessment 09/Rotated Digits.py"}]}],"sources":["solutions"]},"topic-rotatingthebox":{"key":"topic-rotatingthebox","number":null,"title":"Rotating the Box","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Rotating the Box.py","code":"class Solution:\n    def rotateTheBox(self, box: List[List[str]]) -> List[List[str]]:\n        rows, cols, result = len(box), len(box[0]), []\n        for r in range(rows):\n            for c in range(cols - 2, -1, -1):\n                if box[r][c] == '#':\n                    finalIndex = c + 1\n                    while finalIndex < cols and box[r][finalIndex] == '.':\n                        finalIndex += 1\n                    if box[r][finalIndex - 1] == '.':\n                        box[r][c], box[r][finalIndex - 1] = box[r][finalIndex - 1], box[r][c]\n        for c in range(cols):\n            row = []\n            for r in range(rows):\n                row.append(box[r][c])\n            result.append(row[::-1])\n        return result","hash":"9a16f1d10ca1eb06069d9c419f2b225d7cdf670d55601d08e57fade556f6e90b","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 52/Rotating the Box.py"}]}],"sources":["solutions"]},"topic-rottingoranges":{"key":"topic-rottingoranges","number":null,"title":"Rotting Oranges","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Rotting Oranges.py","code":"class Solution:\n    def orangesRotting(self, grid: List[List[int]]) -> int:\n        ROTTEN_ORANGE = 2\n        FRESH_ORANGE = 1\n        DIRECTIONS = [(1, 0), (-1, 0), (0, 1), (0, -1)]\n        queue = deque()\n        numberOfRows, numberOfColumns = len(grid), len(grid[0])\n        freshOranges = 0\n        for rowNumber in range(numberOfRows):\n            for columnNumber in range(numberOfColumns):\n                if grid[rowNumber][columnNumber] == ROTTEN_ORANGE:\n                    queue.append((rowNumber, columnNumber))\n                elif grid[rowNumber][columnNumber] == FRESH_ORANGE:\n                    freshOranges += 1\n        queue.append((-1, -1))\n        minutesElapsed = -1\n        while queue:\n            rowNumber, columnNumber = queue.popleft()\n            if rowNumber == -1:\n                minutesElapsed += 1\n                if queue:\n                    queue.append((-1, -1))\n            else:\n                for direction in DIRECTIONS:\n                    neighbourRow, neighbourColumn = rowNumber + direction[0], columnNumber + direction[1]\n                    if numberOfRows > neighbourRow >= 0 and numberOfColumns > neighbourColumn >= 0:\n                        if grid[neighbourRow][neighbourColumn] == FRESH_ORANGE:\n                            grid[neighbourRow][neighbourColumn] = ROTTEN_ORANGE\n                            freshOranges -= 1\n                            queue.append((neighbourRow, neighbourColumn))\n        return minutesElapsed if freshOranges == 0 else -1","hash":"30f65a3f9da0600b79e9c5520762622903aaa0e50dd40b165fdeacebff7799ba","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Rotting Oranges.py"}]}],"sources":["solutions"]},"topic-runningsumof1darray":{"key":"topic-runningsumof1darray","number":null,"title":"Running Sum of 1d Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Running Sum of 1d Array.py","code":"class Solution:\n    def runningSum(self, nums: List[int]) -> List[int]:\n        result = [0] * len(nums)\n        result[0] = nums[0]\n        for i in range(1, len(nums)):\n            result[i] = result[i - 1] + nums[i]\n        return result","hash":"d5d52acbb8d58be4780b6b436e5decbdc0e45931bf427440df5547d3c26c1f4f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-05 Leetcoding Challenge/Running Sum of 1d Array.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-06 Leetcoding Challenge/Running Sum of 1d Array.py"}]},{"language":"python","name":"Running Sum of 1d Array.py","code":"class Solution:\n    def runningSum(self, nums: List[int]) -> List[int]:\n        result = [nums[0]]\n        for num in nums[1:]:\n            result.append(result[-1] + num)\n        return result","hash":"39c4b1a622ca3d58a7b6734f6bfdae6206f6b5004d6afd4f01770be70f42def7","origins":[{"source":"solutions","path":"Running Sum of 1d Array.py"}]}],"sources":["solutions"]},"topic-russiandollenvelopes":{"key":"topic-russiandollenvelopes","number":null,"title":"Russian Doll Envelopes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Russian Doll Envelopes.py","code":"class Solution:\n    def maxEnvelopes(self, envelopes: List[List[int]]) -> int:\n        envelopes.sort(key = lambda x:(x[0], -x[1]))\n        def LIS(nums):\n            dp = []\n            for num in nums:\n                index = bisect.bisect_left(dp, num)\n                if index == len(dp):\n                    dp.append(num)\n                else:\n                    dp[index] = num\n            return len(dp)\n        return LIS([x[1] for x in envelopes])","hash":"1a38e610ab945baf3aa02cb27ed3d90dc82475f4266450f6facce9192b0ffd95","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-03 Leetcoding Challenge/Russian Doll Envelopes.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Russian Doll Envelopes.py"}]}],"sources":["solutions"]},"topic-scoreofparentheses":{"key":"topic-scoreofparentheses","number":null,"title":"Score of Parentheses","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Score of Parentheses.py","code":"class Solution:\n    def scoreOfParentheses(self, S: str) -> int:\n        result = bal = 0\n        for i, x in enumerate(S):\n            if x == '(':\n                bal += 1\n            else:\n                bal -= 1\n                if S[i - 1] == '(':\n                    result += 1 << bal\n        return result","hash":"5626c5fae3abc8ef70e6be939cc2b3495749f32f7d9063dfa27e04c84adfe707","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/Score of Parentheses.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Score of Parentheses.py"}]}],"sources":["solutions"]},"topic-searchforarange":{"key":"topic-searchforarange","number":null,"title":"Search for a Range","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Search for a Range.py","code":"class Solution:\n    def searchRange(self, nums: List[int], target: int) -> List[int]:\n        def indexSearch(nums, target, left):\n            low = 0\n            high = len(nums)\n            while low < high:\n                mid = (low + high) // 2\n                if nums[mid] > target or (left and target == nums[mid]):\n                    high = mid\n                else:\n                    low = mid + 1\n            return low\n        \n        leftIndex = indexSearch(nums, target, True)\n        if leftIndex == len(nums) or nums[leftIndex] != target:\n            return [-1, -1]\n        else:\n            return [leftIndex, indexSearch(nums, target, False) - 1]","hash":"d1db21b5d54c6b04873df06a55e672a0c0e2b34860150bc79af95e4726aebe04","origins":[{"source":"solutions","path":"Binary Search/Search for a Range.py"}]}],"sources":["solutions"]},"topic-searchinabinarysearchtree":{"key":"topic-searchinabinarysearchtree","number":null,"title":"Search in a Binary Search Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Search in a Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def searchBST(self, root: TreeNode, val: int) -> TreeNode:\n        if root is None:\n            return root\n        if root.val == val:\n            return root\n        if val < root.val:\n            return self.searchBST(root.left, val)\n        else:\n            return self.searchBST(root.right, val)","hash":"0b6e0514b02315798007fd2f9c2c483caabce0ab3f1a10898f54c0236b8012dd","origins":[{"source":"solutions","path":"Binary Search Tree/Search in a Binary Search Tree.py"}]},{"language":"python","name":"Search in a Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def searchBST(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:\n        if root is None:\n            return root\n        if root.val == val:\n            return root\n        if val < root.val:\n            return self.searchBST(root.left, val)\n        else:\n            return self.searchBST(root.right, val)","hash":"72460585a9c20e1b9bfb0b5025d988614b5c8a431b60d2022d4708c25e8547ae","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-04 Leetcoding Challenge/Search in a Binary Search Tree.py"}]},{"language":"python","name":"Search in a Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def searchBST(self, root: TreeNode, val: int) -> TreeNode:\n        node = root\n        while node:\n            if node.val == val:\n                return node\n            elif val < node.val:\n                node = node.left\n            else:\n                node = node.right\n        return None","hash":"48b7763d657738531e3e12741d041e557b824b8f98ca49d2318e711ce6bd9605","origins":[{"source":"solutions","path":"Search in a Binary Search Tree.py"}]}],"sources":["solutions"]},"topic-searchinabinarysearchtreeiterative":{"key":"topic-searchinabinarysearchtreeiterative","number":null,"title":"Search in a Binary Search Tree Iterative","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Search in a Binary Search Tree - Iterative.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def searchBST(self, root: TreeNode, val: int) -> TreeNode:\n        node = root\n        while node:\n            if node.val == val:\n                return node\n            elif val < node.val:\n                node = node.left\n            else:\n                node = node.right\n        return None","hash":"48b7763d657738531e3e12741d041e557b824b8f98ca49d2318e711ce6bd9605","origins":[{"source":"solutions","path":"Recursion I/Search in a Binary Search Tree - Iterative.py"}]}],"sources":["solutions"]},"topic-searchinabinarysearchtreerecursive":{"key":"topic-searchinabinarysearchtreerecursive","number":null,"title":"Search in a Binary Search Tree Recursive","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Search in a Binary Search Tree - Recursive.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def searchBST(self, root: TreeNode, val: int) -> TreeNode:\n        if root is None:\n            return root\n        if root.val == val:\n            return root\n        if val < root.val:\n            return self.searchBST(root.left, val)\n        else:\n            return self.searchBST(root.right, val)","hash":"0b6e0514b02315798007fd2f9c2c483caabce0ab3f1a10898f54c0236b8012dd","origins":[{"source":"solutions","path":"Recursion I/Search in a Binary Search Tree - Recursive.py"}]}],"sources":["solutions"]},"topic-searchinasortedarrayofunknownsize":{"key":"topic-searchinasortedarrayofunknownsize","number":null,"title":"Search in a Sorted Array of Unknown Size","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Search in a Sorted Array of Unknown Size.py","code":"# \"\"\"\n# This is ArrayReader's API interface.\n# You should not implement it, or speculate about its implementation\n# \"\"\"\n#class ArrayReader:\n#    def get(self, index: int) -> int:\n\nclass Solution:\n    def search(self, reader, target):\n        \"\"\"\n        :type reader: ArrayReader\n        :type target: int\n        :rtype: int\n        \"\"\"\n        if reader.get(0) == target:\n            return 0\n        left, right = 0, 1\n        while reader.get(right) < target:\n            left, right = right, right << 1\n        while left <= right:\n            pivot = left + ((right - left) >> 1)\n            num = reader.get(pivot)\n            if num == target:\n                return pivot\n            elif num < target:\n                left = pivot + 1\n            else:\n                right = pivot - 1\n        return -1","hash":"5ecd2469f9e3d212dd3d312c8b121cd91047b5b6936a360e5dac17f0cc12b942","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Search in a Sorted Array of Unknown Size.py"}]}],"sources":["solutions"]},"topic-seatreservationmanager":{"key":"topic-seatreservationmanager","number":null,"title":"Seat Reservation Manager","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Seat Reservation Manager.py","code":"class SeatManager:\n\n    def __init__(self, n: int):\n        self.heap = [i for i in range(1, n + 1)]\n        heapq.heapify(self.heap)\n\n    def reserve(self) -> int:\n        return heapq.heappop(self.heap)\n\n    def unreserve(self, seatNumber: int) -> None:\n        heapq.heappush(self.heap, seatNumber)\n\n\n# Your SeatManager object will be instantiated and called as such:\n# obj = SeatManager(n)\n# param_1 = obj.reserve()\n# obj.unreserve(seatNumber)","hash":"dc7fc423c9bf2160aefeeec729cae6f733e8a77349b358350ccf878d7b471449","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 51/Seat Reservation Manager.py"}]}],"sources":["solutions"]},"topic-secondhighestsalary":{"key":"topic-secondhighestsalary","number":null,"title":"Second Highest Salary","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"sql","name":"Second Highest Salary.sql","code":"# Write your MySQL query statement below\nSELECT (SELECT DISTINCT Salary FROM Employee ORDER BY Salary DESC LIMIT 1 OFFSET 1) AS SecondHighestSalary;","hash":"d9fff1ecd777396e59d7f14eabb5afa856c8d421001e0ea27a707e60aaf73b9e","origins":[{"source":"solutions","path":"Second Highest Salary.sql"}]}],"sources":["solutions"]},"topic-secondlargestdigitinastring":{"key":"topic-secondlargestdigitinastring","number":null,"title":"Second Largest Digit in a String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Second Largest Digit in a String.py","code":"class Solution:\n    def secondHighest(self, s: str) -> int:\n        sortedDigits = sorted(set([int(i) for i in s if i.isdigit()]))\n        return sortedDigits[-2] if len(sortedDigits) > 1 else -1","hash":"5fc855e6a8aba791412b56781ddfef4c352d1f22a8cd508101c02b1373be92e4","origins":[{"source":"solutions","path":"Second Largest Digit in a String.py"}]}],"sources":["solutions"]},"topic-secondminimumnodeinabinarytree":{"key":"topic-secondminimumnodeinabinarytree","number":null,"title":"Second Minimum Node In a Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Second Minimum Node In a Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def findSecondMinimumValue(self, root: Optional[TreeNode]) -> int:\n        self.result, minValue = float('inf'), root.val\n        def dfs(node):\n            if node:\n                if minValue < node.val < self.result:\n                    self.result = node.val\n                else:\n                    dfs(node.left)\n                    dfs(node.right)\n        dfs(root)\n        return self.result if self.result < float('inf') else -1","hash":"49309a4409ed4f1e3bd227f515eab5e38d0f7f5d47ef29a51e64736234ce1c91","origins":[{"source":"solutions","path":"Second Minimum Node In a Binary Tree.py"}]}],"sources":["solutions"]},"topic-selfdividingnumbers":{"key":"topic-selfdividingnumbers","number":null,"title":"Self Dividing Numbers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Self Dividing Numbers.py","code":"class Solution:\n    def selfDividingNumbers(self, left: int, right: int) -> List[int]:\n        result = []\n        for num in range(left, right + 1):\n            for char in str(num):\n                if char == '0' or num % int(char) != 0:\n                    break\n            else:\n                result.append(num)\n        return result","hash":"6bd3ebc8a67af323446c3c100d71122ab624b366b376a6668d4a7e26346ffb5a","origins":[{"source":"solutions","path":"Self Dividing Numbers.py"}]}],"sources":["solutions"]},"topic-senderwithlargestwordcount":{"key":"topic-senderwithlargestwordcount","number":null,"title":"Sender With Largest Word Count","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sender With Largest Word Count.py","code":"class Solution:\n    def largestWordCount(self, messages: List[str], senders: List[str]) -> str:\n        freqMap = defaultdict(int)\n        for i in range(len(senders)):\n            freqMap[senders[i]] += len(messages[i].split(' '))\n        maxCount, sender = 0, ''\n        for s, freq in freqMap.items():\n            if freq > maxCount:\n                maxCount, sender = freq, s\n            elif freq == maxCount and sender < s:\n                sender = s\n        return sender","hash":"d1306a18936d27146e518523f889004444081bfd4652d361449f7261cbbdc8ec","origins":[{"source":"solutions","path":"Sender With Largest Word Count.py"}]}],"sources":["solutions"]},"topic-sequentialdigits":{"key":"topic-sequentialdigits","number":null,"title":"Sequential Digits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sequential Digits.py","code":"class Solution:\n    def sequentialDigits(self, low: int, high: int) -> List[int]:\n        sequence, base, result = '123456789', 10, []\n        for length in range(len(str(low)), len(str(high)) + 1):\n            for start in range(base - length):\n                number = int(sequence[start : start + length])\n                if low <= number <= high:\n                    result.append(number)\n        return result","hash":"73d39779eb42a39c58405745341f522385e2bc53c122c91c61d516f55ae3d270","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Sequential Digits.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/Sequential Digits.py"}]}],"sources":["solutions"]},"topic-serializeanddeserializebst":{"key":"topic-serializeanddeserializebst","number":null,"title":"Serialize and Deserialize BST","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Serialize and Deserialize BST.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, x):\n#         self.val = x\n#         self.left = None\n#         self.right = None\n\nclass Codec:\n\n    def serialize(self, root: TreeNode) -> str:\n        \"\"\"Encodes a tree to a single string.\n        \"\"\"\n        def preorder(node):\n            if node:\n                yield str(node.val)\n                yield from preorder(node.left)\n                yield from preorder(node.right)\n            else:\n                yield 'None'\n        return ','.join(list(preorder(root)))\n\n    def deserialize(self, data: str) -> TreeNode:\n        \"\"\"Decodes your encoded data to tree.\n        \"\"\"\n        nodeVals = data.split(',')\n        def helper():\n            if nodeVals[0] == 'None':\n                nodeVals.pop(0)\n                return None\n            root = TreeNode(int(nodeVals[0]))\n            nodeVals.pop(0)\n            root.left = helper()\n            root.right = helper()\n            return root\n        return helper()\n                    \n\n# Your Codec object will be instantiated and called as such:\n# Your Codec object will be instantiated and called as such:\n# ser = Codec()\n# deser = Codec()\n# tree = ser.serialize(root)\n# ans = deser.deserialize(tree)\n# return ans","hash":"99b6cf37acacefd820246a0bbc578a92042e3d2d34325c2360e0c9cca0b34f5e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Serialize and Deserialize BST.py"}]}],"sources":["solutions"]},"topic-shift2dgrid":{"key":"topic-shift2dgrid","number":null,"title":"Shift 2D Grid","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shift 2D Grid.py","code":"class Solution:\n    def shiftGrid(self, grid: List[List[int]], k: int) -> List[List[int]]:\n        l = [col for row in grid for col in row] # grid to list\n        m, n = len(grid), len(grid[0])\n        k = k % (m * n)\n        l = l[-k:] + l[:-k] # shift k times\n        return [l[i * n: i * n + n] for i in range(m)]  # list to grid","hash":"9a94730c5f70d9c4aea9dcf6695fc1dafd48014b509a351c3b0ef17481f66795","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-04 Leetcoding Challenge/Shift 2D Grid.py"}]}],"sources":["solutions"]},"topic-shoppingoffers":{"key":"topic-shoppingoffers","number":null,"title":"Shopping Offers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shopping Offers.py","code":"class Solution:\n    def shoppingOffers(self, price: List[int], special: List[List[int]], needs: List[int]) -> int:\n        hashMap = {}\n        def dotProduct(a, b):\n            currentSum = 0\n            for x, y in zip(a, b):\n                currentSum += x * y\n            return currentSum\n        def shopping(needs):\n            if sum(needs) == 0:\n                return 0\n            if tuple(needs) in hashMap:\n                return hashMap[tuple(needs)]\n            result = dotProduct(needs, price)\n            for s in special:\n                needsClone = list(needs)\n                j = 0\n                while j < len(needs):\n                    diff = needsClone[j] - s[j]\n                    if diff < 0:\n                        break\n                    needsClone[j] = diff\n                    j += 1\n                if j == len(needs):\n                    result = min(result, s[j] + shopping(needsClone))\n            hashMap[tuple(needs)] = result\n            return result\n        return shopping(needs)","hash":"026fc19549a9e33826b6a21a30a115e06c4a7779cba880533aed7ed253489e99","origins":[{"source":"solutions","path":"Shopping Offers.py"}]}],"sources":["solutions"]},"topic-shortestdistancetoacharacter":{"key":"topic-shortestdistancetoacharacter","number":null,"title":"Shortest Distance to a Character","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shortest Distance to a Character.py","code":"class Solution:\n    def shortestToChar(self, s: str, c: str) -> List[int]:\n        charIndex, result = float('-inf'), [float('inf')] * len(s)\n        for i, char in enumerate(s):\n            if char == c:\n                charIndex, result[i] = i, 0\n            else:\n                result[i] = min(result[i], i - charIndex)\n        charIndex = float('inf')\n        for i in range(len(s) - 1, -1, -1):\n            if s[i] == c:\n                charIndex, result[i] = i, 0\n            else:\n                result[i] = min(result[i], charIndex - i)\n        return result","hash":"795e5bf19a5618a27164a0f8ababd32dc9407280a0ca921e99fb667dd0e80dd4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/Shortest Distance to a Character.py"}]}],"sources":["solutions"]},"topic-shortestdistancetotargetcolor":{"key":"topic-shortestdistancetotargetcolor","number":null,"title":"Shortest Distance to Target Color","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shortest Distance to Target Color.py","code":"class Solution:\n    def shortestDistanceColor(self, colors: List[int], queries: List[List[int]]) -> List[int]:\n        n = len(colors)\n        leftmost, rightmost, distance = [n-1, n-1, n-1], [0, 0, 0], [[-1] * n for _ in range(3)]\n        for i in range(n):\n            color = colors[i] - 1\n            for j in range(rightmost[color], i + 1):\n                distance[color][j] = i - j\n            rightmost[color] = i + 1\n        for i in range(n - 1, -1, -1):\n            color = colors[i] - 1\n            for j in range(leftmost[color], i - 1, -1):\n                if distance[color][j] == -1 or distance[color][j] > j - i:\n                    distance[color][j] = j - i\n            leftmost[color] = i - 1\n        return [distance[color - 1][index] for index, color in queries]","hash":"bc1d06354c17f7470db6eb220f46f674bb3c32687cdd80ea082a180e9fe58f76","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-06 Leetcoding Challenge/Shortest Distance to Target Color.py"}]}],"sources":["solutions"]},"topic-shortestpathvisitingallnodes":{"key":"topic-shortestpathvisitingallnodes","number":null,"title":"Shortest Path Visiting All Nodes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shortest Path Visiting All Nodes.py","code":"class Solution:\n    def shortestPathLength(self, graph: List[List[int]]) -> int:\n        if len(graph) == 1:\n            return 0\n        n, steps = len(graph), 0\n        endingMask, queue = (1 << n) - 1, [(node, 1 << node) for node in range(n)]\n        seen = set(queue)\n        while queue:\n            nextQueue = []\n            for i in range(len(queue)):\n                node, mask = queue[i]\n                for neighbour in graph[node]:\n                    nextMask = mask | 1 << neighbour\n                    if nextMask == endingMask:\n                        return  1 + steps\n                    if (neighbour, nextMask) not in seen:\n                        seen.add((neighbour, nextMask))\n                        nextQueue.append((neighbour, nextMask))\n            steps += 1\n            queue = nextQueue","hash":"54feddec37b951c1570a1e1e670d6def46a75a7efda9a3aee3517b4c33bc5d2f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/Shortest Path Visiting All Nodes.py"}]}],"sources":["solutions"]},"topic-shortestpathwithalternatingcolors":{"key":"topic-shortestpathwithalternatingcolors","number":null,"title":"Shortest Path with Alternating Colors","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shortest Path with Alternating Colors.py","code":"class Solution:\n    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:\n        graph = defaultdict(list)\n        for redEdge in redEdges:\n            graph[redEdge[0]].append((redEdge[1], 0))\n        for blueEdge in blueEdges:\n            graph[blueEdge[0]].append((blueEdge[1], 1))\n        result = [-1] * n\n        visited = set()\n        # Start with node 0, with number of steps as 0 and undefined color -1.\n        queue = deque([(0, 0, -1)])\n        result[0] = 0\n        visited.add((0, 0))\n        visited.add((0, 1))\n        while queue:\n            node, steps, prevColor = queue.popleft()\n            if node not in graph:\n                continue\n            for neighbour, color in graph[node]:\n                if (neighbour, color) not in visited and color != prevColor:\n                    if result[neighbour] == -1:\n                        result[neighbour] = steps + 1\n                    visited.add((neighbour, color))\n                    queue.append((neighbour, steps + 1, color))\n        return result","hash":"4279d08e51553eeb6f6ff9b417611644792f5487cf65ce009e71a339254dd16e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-02 Leetcoding Challenge/Shortest Path with Alternating Colors.py"}]}],"sources":["solutions"]},"topic-shortestsubarraytoberemovedtomakearraysorted":{"key":"topic-shortestsubarraytoberemovedtomakearraysorted","number":null,"title":"Shortest Subarray to be Removed to Make Array Sorted","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shortest Subarray to be Removed to Make Array Sorted.py","code":"class Solution:\n    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:\n        n = len(arr)\n        if n < 2:\n            return 0\n        last = n - 1\n        while last > 0 and arr[last - 1] <= arr[last]:\n            last -= 1\n        result = last\n        for i in range(n):\n            if i > 0 and arr[i] < arr[i - 1]:\n                break\n            while last < n and (last <= i or arr[last] < arr[i]):\n                last += 1\n            result = min(result, last - i - 1)\n        return result","hash":"8cd1503dbc32613028f5501746c28db2b0b0c06d11b03dda26f3753ba71b3a98","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 34/Shortest Subarray to be Removed to Make Array Sorted.py"}]}],"sources":["solutions"]},"topic-shortestunsortedcontinuoussubarray":{"key":"topic-shortestunsortedcontinuoussubarray","number":null,"title":"Shortest Unsorted Continuous Subarray","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shortest Unsorted Continuous Subarray.py","code":"class Solution:\n    def findUnsortedSubarray(self, nums: List[int]) -> int:\n        currentMin, currentMax, flag, l, r = float('inf'), float('-inf'), False, 0, len(nums) - 1\n        for i in range(1, len(nums)):\n            if nums[i] < nums[i - 1]:\n                flag = True\n            if flag:\n                currentMin = min(currentMin, nums[i])\n        flag = False\n        for i in range(len(nums) - 2, -1, -1):\n            if nums[i] > nums[i + 1]:\n                flag = True\n            if flag:\n                currentMax = max(currentMax, nums[i])\n        while l < len(nums):\n            if currentMin < nums[l]:\n                break\n            l += 1\n        while r > -1:\n            if currentMax > nums[r]:\n                break\n            r -= 1\n        return 0 if r - l < 0 else r - l + 1","hash":"16cab5d54a6445da0106a79b98a726a226c23107de8dc77b97eec973c9b35914","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/Shortest Unsorted Continuous Subarray.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Shortest Unsorted Continuous Subarray.py"}]}],"sources":["solutions"]},"topic-shortestwaytoformstring":{"key":"topic-shortestwaytoformstring","number":null,"title":"Shortest Way to Form String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shortest Way to Form String.py","code":"class Solution:\n    def shortestWay(self, source: str, target: str) -> int:\n        hashMap = defaultdict(list)\n        for index, ch in enumerate(source):\n            hashMap[ch].append(index)\n        i, j, count = -1, 0, 1\n        targetLength = len(target)\n        while j < targetLength:\n            if target[j] not in hashMap:\n                return -1\n            index = bisect.bisect(hashMap[target[j]], i)\n            if index == len(hashMap[target[j]]):\n                i = -1\n                count += 1\n            else:\n                i = hashMap[target[j]][index]\n                j += 1\n        return count","hash":"6891a49047772e22344539b634df2251767cae9c746839be8e761695ff46ab3a","origins":[{"source":"solutions","path":"Mock Interviews/Google/Phone Interview 07/Shortest Way to Form String.py"}]}],"sources":["solutions"]},"topic-shuffleanarray":{"key":"topic-shuffleanarray","number":null,"title":"Shuffle an Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shuffle an Array.py","code":"class Solution:\n\n    def __init__(self, nums: List[int]):\n        self.array = nums\n        self.original = list(nums)\n\n    def reset(self) -> List[int]:\n        \"\"\"\n        Resets the array to its original configuration and return it.\n        \"\"\"\n        self.array = self.original\n        self.original = list(self.original)\n        return self.array\n\n    def shuffle(self) -> List[int]:\n        \"\"\"\n        Returns a random shuffling of the array.\n        \"\"\"\n        for i in range(len(self.array)):\n            swapIndex = random.randrange(i, len(self.array))\n            self.array[i], self.array[swapIndex] = self.array[swapIndex], self.array[i]\n        return self.array\n\n\n# Your Solution object will be instantiated and called as such:\n# obj = Solution(nums)\n# param_1 = obj.reset()\n# param_2 = obj.shuffle()","hash":"bd8d44aeac3bfc93b5fa7f0a061ce13237f4f80491479b3a3e8163dd7799ee3c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-07 Leetcoding Challenge/Shuffle an Array.py"}]}],"sources":["solutions"]},"topic-shufflestring":{"key":"topic-shufflestring","number":null,"title":"Shuffle String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shuffle String.py","code":"class Solution:\n    def restoreString(self, s: str, indices: List[int]) -> str:\n        length = len(s)\n        result = [''] * length\n        for i in range(length):\n            result[indices[i]] = s[i]\n        return ''.join(result)","hash":"897111d02ccf6bf6cd43c9c15cd47d9e5f0be31833953af3406ac43a8e506996","origins":[{"source":"solutions","path":"Shuffle String.py"}]}],"sources":["solutions"]},"topic-shufflethearray":{"key":"topic-shufflethearray","number":null,"title":"Shuffle the Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Shuffle the Array.py","code":"class Solution:\n    def shuffle(self, nums: List[int], n: int) -> List[int]:\n        result = [float('-inf')] * (2 * n)\n        for i in range(n):\n            result[2 * i] = nums[i]\n            result[(2 * i) + 1] = nums[n + i]\n        return result","hash":"a8011d8e32aef14819240e5d7d0b911d85e83459690aabe28d1b0e950690b4bb","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-02 Leetcoding Challenge/Shuffle the Array.py"},{"source":"solutions","path":"Shuffle the Array.py"}]}],"sources":["solutions"]},"topic-similarrgbcolor":{"key":"topic-similarrgbcolor","number":null,"title":"Similar RGB Color","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Similar RGB Color.py","code":"class Solution:\n    def similarRGB(self, color: str) -> str:\n        def similar(hexNumber):\n            q, r = divmod(int(hexNumber, 16), 17)\n            if r > 8:\n                q += 1\n            return '{:02x}'.format(17 * q)\n        return '#' + similar(color[1:3]) + similar(color[3:5]) + similar(color[5:])","hash":"6be2f6db09a032a2647777dd07b19df6ea8e441f74fe121651b5893f43fca1ab","origins":[{"source":"solutions","path":"Similar RGB Color.py"}]}],"sources":["solutions"]},"topic-simplebanksystem":{"key":"topic-simplebanksystem","number":null,"title":"Simple Bank System","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Simple Bank System.py","code":"class Bank:\n\n    def __init__(self, balance: List[int]):\n        self.balance = balance\n        self.numberofAccounts = len(balance)\n    \n    def _isAccountNumberValid(self, account: int) -> bool:\n        return 1 <= account <= self.numberofAccounts\n    \n    def _canProceedWithWithdrawal(self, account: int, money: int) -> bool:\n        return self._isAccountNumberValid(account) and self.balance[account - 1] >= money\n\n    def transfer(self, account1: int, account2: int, money: int) -> bool:\n        if self._canProceedWithWithdrawal(account1, money) and self._isAccountNumberValid(account2):\n            self.balance[account1 - 1] -= money\n            self.balance[account2 - 1] += money\n            return True\n        return False\n\n    def deposit(self, account: int, money: int) -> bool:\n        if self._isAccountNumberValid(account):\n            self.balance[account - 1] += money\n            return True\n        return False\n\n    def withdraw(self, account: int, money: int) -> bool:\n        if self._canProceedWithWithdrawal(account, money):\n            self.balance[account - 1] -= money\n            return True\n        return False\n\n\n# Your Bank object will be instantiated and called as such:\n# obj = Bank(balance)\n# param_1 = obj.transfer(account1,account2,money)\n# param_2 = obj.deposit(account,money)\n# param_3 = obj.withdraw(account,money)","hash":"f86a5bbd324c97c5ba93fdf171e5c3db238e11c01729d0092cf0ed033cf10f56","origins":[{"source":"solutions","path":"Simple Bank System.py"}]}],"sources":["solutions"]},"topic-simplifiedfractions":{"key":"topic-simplifiedfractions","number":null,"title":"Simplified Fractions","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Simplified Fractions.py","code":"class Solution:\n    def simplifiedFractions(self, n: int) -> List[str]:\n        result = []\n        for denominator in range(2, n + 1):\n            for numerator in range(1, denominator):\n                if math.gcd(numerator, denominator) == 1:\n                    result.append(\"{}/{}\".format(numerator, denominator))\n        return result","hash":"104d28d0db640fb9275cb5da6586a175fa35c5f73d65ad0ff208576919f3c2cd","origins":[{"source":"solutions","path":"Simplified Fractions.py"}]}],"sources":["solutions"]},"topic-singlenumber":{"key":"topic-singlenumber","number":null,"title":"Single Number","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Single Number.py","code":"class Solution:\n    def singleNumber(self, nums: List[int]) -> int:\n        result = 0\n        for num in nums:\n            result ^= num\n        return result","hash":"d52ff96ef48b0bddda68a701fd5f909f3c61d45e762dcbca02bab7a3e775b602","origins":[{"source":"solutions","path":"Hash Table/Single Number.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/Single Number.py"}]}],"sources":["solutions"]}});
